from PIL import Image
import numpy as np
from collections import deque
for cam in ['egocentric_mirrored_camera','over_shoulder_left_camera']:
 im=np.asarray(Image.open('/app/output/initial_'+cam+'.jpg').convert('RGB')).astype(int)
 R,G,B=im.transpose(2,0,1)
 mask=(R>70)&(R>G*1.45)&(R>B*1.35)&(G<100)&(B<100)
 H,W=mask.shape; seen=np.zeros_like(mask); cs=[]
 for y,x in zip(*np.where(mask)):
  if seen[y,x]: continue
  st=[(y,x)];seen[y,x]=1; pts=[]
  while st:
   yy,xx=st.pop();pts.append((yy,xx))
   for dy in (-1,0,1):
    for dx in (-1,0,1):
     ny,nx=yy+dy,xx+dx
     if 0<=ny<H and 0<=nx<W and mask[ny,nx] and not seen[ny,nx]:seen[ny,nx]=1;st.append((ny,nx))
  if len(pts)>10:
   a=np.array(pts);cs.append((len(pts),tuple(np.round(a[:,1].mean(),1)),tuple(np.round(a[:,0].mean(),1)),(int(a[:,1].min()),int(a[:,0].min()),int(a[:,1].max()),int(a[:,0].max()))))
 print(cam,sorted(cs,reverse=True)[:15])
